md+=['','Alle neu ausgeführten Einzelprüfungen und ihre Logs sind im JSON unter `testEvidence` verzeichnet. Deno wurde ohne Netzrecht und mit `--cached-only` ausgeführt. Die sechs neuen Handlerfälle sowie gezielte alte Nachbarguards bestehen; das übrige Handlerfile wurde bewusst nicht als vollständige Suite gestartet.','']
(OUT/'REVIEW.md').write_text('\n'.join(md))
print(json.dumps({'issues':len(issues),'criteria':sum(len(x['criteria']) for x in issues),'files':len(sourcefiles),'logs':len(testLogs),'md':str(OUT/'REVIEW.md'),'json':str(OUT/'REVIEW.json')},ensure_ascii=False))
